    [ab('轻功与敏捷配合','受训身法、快速移动与姐妹间熟悉的协作。','不是瞬移或隐形；需要落点、空间与身体状态。'),ab('机敏观察','借身形、时机和现场细节进行侦察与恶作剧。','不能自动读取秘密或让对方永远上当。')],
